CREATE TABLE voice_deployment_guard (
 singleton BIGINT PRIMARY KEY CHECK(singleton=1), token TEXT COLLATE "C" NOT NULL, target TEXT COLLATE "C" NOT NULL, created_at TEXT COLLATE "C" NOT NULL
)

CREATE TABLE writing_defaults (
        user_id TEXT COLLATE "C" PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, settings_json TEXT COLLATE "C" NOT NULL
      )
